// Generated by packages/academy/scripts/build-content.ts. Don't edit by hand.
export default JSON.parse("{\"2.11.1\":{\"unit\":\"2.11\",\"courseId\":\"2.11.1\",\"bridge\":\"In 2.10.9 you saw that only small size caps a news shock. In 1.4.4 you sized one trade from its stop, and in 2.4.6 you measured ATR. Here you size LABX and LABZ so one ATR of movement costs both the same.\",\"hook\":{\"prompt\":\"You buy 50 units of LABX (ATR 2.00) and 50 units of LABZ (ATR 0.50). Which position moves your account more on a typical day?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"LABX\"},{\"id\":\"b\",\"label\":\"LABZ\"},{\"id\":\"c\",\"label\":\"The same: 50 units each\"}],\"answer\":\"a\"},\"compare\":\"You picked {yours}. One ATR on 50 LABX is 50 × 2.00 = 100.00; on 50 LABZ it's 50 × 0.50 = 25.00. Same units, four times the swing.\",\"concept\":\"percent-volatility-sizing\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"One ATR, one price\",\"text\":\"[[volatility-sizing|Volatility sizing]] sets the size so one [[atr|ATR]] of movement costs the same share of [[equity]] in every instrument. Pick that share, v, then: units = equity × v ÷ ATR per unit. The Turtle traders sized this way, calling one ATR 'N'. LABZ is a calmer simulated instrument, priced near 40.00.\",\"figure\":{\"kind\":\"formula\",\"boxes\":[{\"text\":\"Equity × v\"},{\"text\":\"ATR per unit\"},{\"text\":\"Units\"}],\"operators\":[\"÷\",\"=\"],\"steps\":[\"v is the share of equity one ATR may cost, such as 0.5%.\",\"Divide that money by how far one unit moves in an ATR.\",\"Round down to whole units.\"]}},{\"kind\":\"worked\",\"title\":\"Same budget, two instruments\",\"lines\":[\"Equity 10,000.00, v = 0.5%: one ATR may cost 50.00.\",\"LABX, ATR 2.00: 50.00 ÷ 2.00 = 25 units.\",\"LABZ, ATR 0.50: 50.00 ÷ 0.50 = ?\"],\"ask\":{\"answer\":100,\"tolerance\":0,\"unit\":\"units\",\"feedback\":[{\"value\":25,\"text\":\"That's the LABX size. LABZ moves a quarter as much per unit, so it takes four times the units.\"},{\"value\":0.01,\"text\":\"That divides the ATR by the budget. Put the money on top: 50.00 ÷ 0.50.\"}],\"correct\":\"Right. 100 units of LABZ move 50.00 per ATR, exactly like 25 units of LABX.\"},\"after\":\"Both positions now swing about 50.00 on a typical day: 0.5% of the account each.\",\"concept\":\"percent-volatility-sizing\"},{\"kind\":\"worked\",\"title\":\"Stop at two ATRs, after costs\",\"lines\":[\"Put the stop 2 ATRs from the entry: it then costs about 2 × 0.5% = 1% of equity, 100.00.\",\"LABX, entry 100.00, stop 96.00: 25 units lose 100.00 on price, 102.45 with both commissions.\",\"24 units lose 96.00 + 1.20 + 1.16 = 98.36.\",\"Most whole LABX units within 100.00 = ?\"],\"ask\":{\"answer\":24,\"tolerance\":0,\"unit\":\"units\",\"feedback\":[{\"value\":25,\"text\":\"25 is the size before costs. With both commissions it loses 102.45, over 100.00.\"}],\"correct\":\"Right. 24 units: 98.36 at the stop.\"},\"after\":\"LABZ, entry 40.00 and stop 39.00, is yours to size in the Try.\",\"concept\":\"cost-adjusted-sizing\"},{\"kind\":\"figure\",\"title\":\"What a typical day costs\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Fixed: 50 LABX\",\"value\":100,\"role\":\"down\"},{\"label\":\"Fixed: 50 LABZ\",\"value\":25,\"role\":\"neutral\"},{\"label\":\"By ATR: 25 LABX\",\"value\":50,\"role\":\"accent\"},{\"label\":\"By ATR: 100 LABZ\",\"value\":50,\"role\":\"accent\"}],\"unit\":\"vUSD\",\"steps\":[\"Fixed units: one ATR costs 100.00 on LABX and 25.00 on LABZ.\",\"Sized by ATR: 25 × 2.00 = 50.00 and 100 × 0.50 = 50.00.\",\"Each position now carries the same weight in the account.\"]},\"text\":\"Fixed units let the wilder instrument dominate the account. Volatility sizing evens the two out.\",\"concept\":\"percent-volatility-sizing\"},{\"kind\":\"predict\",\"title\":\"The ATR doubles\",\"prompt\":\"You hold 100 LABZ, sized when its ATR was 0.50. Overnight news doubles its daily range to about 1.00. What happens to the position's typical daily swing?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"It stays at 50.00: the units didn't change\",\"feedback\":\"The units didn't change, but each one now moves twice as far: 100 × 1.00 = 100.00.\"},{\"id\":\"b\",\"label\":\"It doubles, to about 100.00\"},{\"id\":\"c\",\"label\":\"It halves\",\"feedback\":\"A bigger range makes every unit move more, not less: 100 × 1.00 = 100.00.\"}],\"answer\":\"b\"},\"reveal\":\"It doubles: 100 × 1.00 = 100.00 per ATR, 1% of equity instead of 0.5%. Resize: 50.00 ÷ 1.00 = 50 units. Don't wait for ATR to tell you. If the range stays at 1.00, a 14-day ATR reads 0.54 the next day and 0.76 ten days later.\",\"concept\":\"percent-volatility-sizing\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"Equal risk per ATR doesn't make positions independent. 25 LABX and 100 LABZ each swing 50.00, but if both fall on the same news, you lose on both. Volatility sizing evens the size of each bet. It says nothing about whether they are the same bet: that's 2.11.3.\"}],\"task\":{\"widget\":\"position-size\",\"goal\":\"LABZ: entry 40.00, ATR 0.50, stop two ATRs lower at 39.00. Your budget is 1% of 10,000.00. Type the most units that lose no more than 100.00 at the stop, costs included.\",\"start\":{\"account\":10000,\"riskPct\":1,\"entry\":40,\"stop\":39,\"units\":100},\"locked\":[\"account\",\"riskPct\",\"entry\",\"stop\"],\"hidden\":[\"simpleQty\",\"qty\"],\"success\":{\"all\":[{\"field\":\"units\",\"eq\":96},{\"field\":\"stop\",\"eq\":39},{\"field\":\"riskPct\",\"eq\":1}]},\"feedback\":[{\"when\":{\"field\":\"units\",\"eq\":100},\"text\":\"100 units is the size before costs. With both commissions they lose 103.95 at the stop, over 100.00.\"},{\"when\":{\"field\":\"units\",\"eq\":97},\"text\":\"97 units lose 100.84 with both commissions, just over 100.00.\"},{\"when\":{\"field\":\"units\",\"gt\":97},\"text\":\"{units} units would lose {lossAtStop:2} at the stop, over 100.00.\"},{\"when\":{\"field\":\"units\",\"lt\":96},\"text\":\"{units} units fit, losing {lossAtStop:2}. One more would still fit: find the most that does.\"}],\"correct\":\"Right. 96 units lose 99.80 at the stop. With 24 LABX, each position swings 48.00 per ATR, and together they hold 2,400.00 + 3,840.00 = 6,240.00, under the account.\",\"hints\":[\"Each unit loses 1.00 at the stop, plus the two commissions.\",\"Commissions per unit: 0.05% of 40.00 plus 0.05% of 39.00, about 0.04.\",\"100.00 ÷ 1.0395 = 96.2. Round down, then check the loss.\"],\"showMe\":{\"units\":96},\"concept\":\"percent-volatility-sizing\"},\"check\":[\"q-2.11.1-1\",\"q-2.11.1-2\",\"q-2.11.1-3\"],\"recap\":{\"takeaways\":[\"Volatility sizing: units = equity × v ÷ ATR. At v = 0.5%, one ATR costs 50.00 everywhere.\",\"Fixed units let wild instruments dominate: 50 LABX swing 100.00 a day, 50 LABZ 25.00.\",\"ATR lags after volatility jumps, and equal size per ATR doesn't make positions independent.\"],\"next\":\"Next, 2.11.2: portfolio heat, the open risk of all your positions added up and kept under a cap.\"}},\"2.11.2\":{\"unit\":\"2.11\",\"courseId\":\"2.11.2\",\"bridge\":\"In 2.11.1 you gave each position the same cost per ATR, with a stop near 1% risk. Each trade was still sized alone. Here you add up the open risk of every position, pending orders included, and cap the total: portfolio heat.\",\"hook\":{\"prompt\":\"Five trades, each risking 1%, all hit their stops in one afternoon. How much has the account lost?\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":10,\"step\":0.5,\"unit\":\"%\",\"start\":0,\"answer\":5,\"tolerance\":0,\"feedback\":[{\"from\":0,\"to\":4.5,\"text\":\"Each stop costs 1% of the account, and all five were hit: they add up.\"},{\"from\":5.5,\"to\":10,\"text\":\"Five stops at 1% each cost 5%. Only slippage or a gap would push it past that.\"}]},\"compare\":\"You answered {yours}%. Five stops at 1% each: 5%, or 500.00 of 10,000.00, before slippage. That total is your portfolio heat.\",\"concept\":\"portfolio-heat\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Heat\",\"text\":\"[[portfolio-heat|Portfolio heat]] is the sum of the [[open-risk|open risk]] of every position, as a share of equity: what you'd lose if every stop were hit at once. Risk per trade caps one loss. Heat caps a bad afternoon, when news, a gap or a sharp turn hits all your positions together.\"},{\"kind\":\"worked\",\"title\":\"Add it up\",\"lines\":[\"Equity 10,000.00. Four open trades risk 100.00, 50.00, 100.00 and 150.00.\",\"As shares of equity: 1% + 0.5% + 1% + 1.5%.\",\"Portfolio heat = ?\"],\"ask\":{\"answer\":4,\"tolerance\":0.01,\"unit\":\"%\",\"feedback\":[{\"value\":1.5,\"text\":\"That's the largest single risk. Heat adds all of them.\"},{\"value\":400,\"text\":\"400.00 is the heat in vUSD. As a share of 10,000.00, it's a percentage.\"}],\"correct\":\"Right. 4% heat: 400.00 if every stop fills as planned.\"},\"after\":\"With a 5% cap, only 1% is left for any new trade.\",\"concept\":\"portfolio-heat\"},{\"kind\":\"figure\",\"title\":\"The heat bar\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Trade A\",\"value\":1,\"role\":\"accent\"},{\"label\":\"Trade B\",\"value\":0.5,\"role\":\"accent\"},{\"label\":\"Trade C\",\"value\":1,\"role\":\"accent\"},{\"label\":\"Trade D\",\"value\":1.5,\"role\":\"accent\"},{\"label\":\"Total heat\",\"value\":4,\"role\":\"down\"},{\"label\":\"Cap\",\"value\":5,\"role\":\"neutral\"}],\"unit\":\"%\",\"steps\":[\"Four open trades: 1%, 0.5%, 1% and 1.5% of equity.\",\"Together: 4% heat, under a 5% cap.\",\"The cap is a convention: practitioners use 4–8%, often 5–6%.\"]},\"text\":\"No study fixes the right cap. Pick one before you trade, write it into your plan and check it before every order.\",\"concept\":\"portfolio-heat\"},{\"kind\":\"predict\",\"title\":\"A stop at breakeven\",\"prompt\":\"You moved one trade's stop to its entry price, 100.00. Does that position still count in your heat?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"No: at breakeven it can't lose\",\"feedback\":\"It can't lose at the stop. But a gap can open below the stop, and it fills at the first price available.\"},{\"id\":\"b\",\"label\":\"Yes: a gap can jump past the stop\"}],\"answer\":\"b\"},\"reveal\":\"Yes. Say 50 units, stop at 100.00. If LABX opens at 97.00, the stop fills there: 150.00 on price plus 2.50 and 2.43 of commissions, 154.93. A 'zero-risk' position lost 1.5% of the account. Count a gap allowance for it.\",\"concept\":\"gap-risk\"},{\"kind\":\"match\",\"title\":\"What counts in heat\",\"prompt\":\"Sort each item: does it count toward your heat?\",\"pairs\":[{\"left\":\"An open LABX long with its initial stop\",\"right\":\"Counts\"},{\"left\":\"A pending buy stop order, with its own stop\",\"right\":\"Counts\",\"wrong\":\"It can fill while you're away, and its risk is live at once. Count it as if filled.\"},{\"left\":\"A position with its stop at breakeven\",\"right\":\"Counts\",\"wrong\":\"Its loss at the stop is zero, but a gap can fill it far lower. Count a gap allowance.\"},{\"left\":\"A trade stopped out this morning\",\"right\":\"Doesn't count\",\"wrong\":\"That loss is already out of your equity. Heat counts only what you could still lose.\"},{\"left\":\"A setup on your watchlist, no order placed\",\"right\":\"Doesn't count\",\"wrong\":\"Nothing can fill, so nothing is at risk yet. Count it the moment you place the order.\"}],\"columns\":[\"Item\",\"Heat\"],\"correct\":\"Right. Heat counts everything that can still lose money: positions, [[pending-order|pending orders]] and gap risk.\",\"concept\":\"portfolio-heat\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"Check heat before every order: current heat plus the new trade's risk must stay under the cap. If it doesn't fit, resize the new trade or skip it. Never raise the cap to fit a trade you like.\"}],\"task\":{\"widget\":\"position-size\",\"goal\":\"Heat is 4.0% with a 5% cap. A new LABZ trade, entry 40.00 and stop 39.00, was planned at 1.5% risk. Set its risk so the trade fits under the cap.\",\"start\":{\"account\":10000,\"riskPct\":1.5,\"entry\":40,\"stop\":39},\"locked\":[\"account\",\"entry\",\"stop\"],\"success\":{\"field\":\"riskPct\",\"lte\":1},\"feedback\":[{\"when\":{\"field\":\"riskPct\",\"gt\":1},\"text\":\"At {riskPct}%, heat would be 4.0% + {riskPct}%, over the 5% cap. Lower it.\"}],\"correct\":\"Right. At 1%, the budget is 100.00 and the size 96 units, losing 99.80 at the stop. Heat lands at 5.0%, right at the cap. Skipping the trade would respect it too.\",\"hints\":[\"Room under the cap = cap − current heat.\",\"5% − 4.0% = 1.0%. The new trade can risk at most that.\"],\"showMe\":{\"riskPct\":1},\"concept\":\"portfolio-heat\"},\"check\":[\"q-2.11.2-1\",\"q-2.11.2-2\",\"q-2.11.2-3\"],\"recap\":{\"takeaways\":[\"Heat = the sum of open risk ÷ equity: 1% + 0.5% + 1% + 1.5% = 4%.\",\"Before each order, heat plus the new risk must fit the cap. Resize or skip.\",\"Pending orders count, and a breakeven stop still carries gap risk.\"],\"next\":\"Next, 2.11.3: correlation, and why positions that move together add up to fewer bets than you count.\"}},\"2.11.3\":{\"unit\":\"2.11\",\"courseId\":\"2.11.3\",\"bridge\":\"In 2.11.2 you added open risks as if each stop could fail alone. Positions that move together fail together. Like the five oscillators of 2.8.9, which were one piece of evidence, correlated positions can be one bet. Here you count the bets you really hold.\",\"hook\":{\"prompt\":\"You hold LABX and LABY long, 1% risk each. They move together, with a correlation of 0.9. Is that 2% of independent risk, or close to one 2% bet?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"2% of independent risk\"},{\"id\":\"b\",\"label\":\"Close to one 2% bet\"}],\"answer\":\"b\"},\"compare\":\"You picked {yours}. Together they swing like 1.95% of risk; two unrelated 1% positions would swing like 1.41%. At 0.9 it's nearly one bet.\",\"concept\":\"correlation-and-concentration\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Same move, same loss\",\"text\":\"[[correlation|Correlation]] runs from −1 to +1. LABY is a simulated instrument that tracks LABX closely: their correlation is usually 0.85 to 0.9. When LABX falls, LABY usually falls too, so their stops tend to be hit together. [[diversification|Diversification]] works only between positions that don't move as one.\"},{\"kind\":\"worked\",\"title\":\"Correlation-adjusted risk\",\"lines\":[\"Two positions with risks a and b and correlation ρ: combined = √(a² + b² + 2ρab).\",\"Unrelated (ρ = 0): √(1 + 1) = 1.41%.\",\"LABX and LABY at ρ = 0.9: √(1 + 1 + 2 × 0.9) = √3.8 = ?\"],\"ask\":{\"answer\":1.95,\"tolerance\":0.01,\"unit\":\"%\",\"feedback\":[{\"value\":2,\"text\":\"2% is the case ρ = 1, a single bet. At 0.9 it's just under: √3.8.\"},{\"value\":1.41,\"text\":\"That's ρ = 0. With ρ = 0.9, add 2 × 0.9 inside the root.\"}],\"correct\":\"Right. 1.95%: almost the full 2% of a single bet.\"},\"after\":\"The formula measures how the pair swings together. If both stops are hit, you still lose the full 2%.\",\"concept\":\"correlation-and-concentration\"},{\"kind\":\"worked\",\"title\":\"Effective bets\",\"lines\":[\"[[effective-bets|Effective bets]] = n ÷ (1 + (n − 1) × ρ), for n positions with average correlation ρ.\",\"Five unrelated positions (ρ = 0): 5 ÷ 1 = 5 bets.\",\"Five positions with ρ = 0.8: 5 ÷ (1 + 4 × 0.8) = 5 ÷ 4.2 = ?\"],\"ask\":{\"answer\":1.19,\"tolerance\":0.01,\"unit\":\"bets\",\"feedback\":[{\"value\":5,\"text\":\"Five is the number of tickets, not of bets. At ρ = 0.8, divide by 4.2.\"},{\"value\":4.2,\"text\":\"4.2 is the divisor. Five positions ÷ 4.2.\"}],\"correct\":\"Right. 1.19: five tickets, a little more than one bet.\"},\"after\":\"A heat cap alone misses this: five positions at 1% with ρ = 0.8 behave like one large one.\",\"concept\":\"correlation-and-concentration\"},{\"kind\":\"figure\",\"title\":\"Correlation under stress\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Days 1–20\",\"value\":0.08,\"role\":\"accent\"},{\"label\":\"Days 21–40\",\"value\":0.2,\"role\":\"accent\"},{\"label\":\"Days 41–60\",\"value\":0.01,\"role\":\"accent\"},{\"label\":\"Days 61–80\",\"value\":0.07,\"role\":\"accent\"},{\"label\":\"Days 81–100\",\"value\":0.24,\"role\":\"accent\"},{\"label\":\"Days 101–120\",\"value\":0.86,\"role\":\"down\"},{\"label\":\"Days 121–140\",\"value\":0.91,\"role\":\"down\"}],\"steps\":[\"Simulated calm: LABX and LABZ barely move together, between 0.01 and 0.24.\",\"A simulated stress episode: 0.86, then 0.91. The 'unrelated' pair now moves as one.\",\"Real markets too: the stock–bond correlation, mostly negative in 2000–2020, was about +0.58 in 2022–2023.\"]},\"text\":\"Correlation of LABX and LABZ over 20-day windows, from a generator. Correlation measured in calm times understates a crisis, when many traders cut risk at the same moment.\",\"concept\":\"correlation-and-concentration\"},{\"kind\":\"match\",\"title\":\"The same bet, in disguise\",\"prompt\":\"In a currency pair, a long buys the first currency and sells the second. Sort each trade by what it does to vUSD.\",\"pairs\":[{\"left\":\"Long vEUR/vUSD\",\"right\":\"Against vUSD\"},{\"left\":\"Short vUSD/vJPY\",\"right\":\"Against vUSD\",\"wrong\":\"vUSD is the first currency here, so a short sells it: a bet against vUSD.\"},{\"left\":\"Short vUSD/vCHF\",\"right\":\"Against vUSD\",\"wrong\":\"Selling vUSD/vCHF sells vUSD for vCHF: another bet against vUSD.\"},{\"left\":\"Long vUSD/vCHF\",\"right\":\"For vUSD\",\"wrong\":\"A long buys the first currency, vUSD.\"},{\"left\":\"Long vEUR/vCHF\",\"right\":\"No vUSD\",\"wrong\":\"Neither currency is vUSD. This trade is about vEUR against vCHF.\"}],\"columns\":[\"Trade\",\"vUSD bet\"],\"correct\":\"Right. The first three are one trade made three times: short vUSD. One dollar rally hits all of them.\",\"concept\":\"correlation-and-concentration\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"Group positions that share a driver, such as one instrument family, one currency or one theme, and count each group as one bet. Correlations measured in calm markets understate stress, so don't count on a low one holding when markets turn.\"},{\"kind\":\"match\",\"title\":\"Two positions under a 1.5% cap\",\"prompt\":\"Each position risks 1%. Correlations: LABX–LABY 0.85; LABZ with either, 0. Sort each combination against a correlation-adjusted heat cap of 1.5%.\",\"pairs\":[{\"left\":\"LABX + LABY\",\"right\":\"Over 1.5%\",\"wrong\":\"√(1 + 1 + 2 × 0.85) = √3.7 = 1.92%, over the cap.\"},{\"left\":\"LABX + LABZ\",\"right\":\"Within 1.5%\",\"wrong\":\"At ρ = 0, √(1 + 1) = 1.41%, inside the cap.\"},{\"left\":\"LABY + LABZ\",\"right\":\"Within 1.5%\",\"wrong\":\"At ρ = 0, √(1 + 1) = 1.41%, inside the cap.\"},{\"left\":\"LABX + LABY + LABZ\",\"right\":\"Over 1.5%\",\"wrong\":\"√(1 + 1 + 1 + 2 × 0.85) = √4.7 = 2.17%, over the cap.\"}],\"columns\":[\"Positions\",\"Adjusted heat\"],\"correct\":\"Right. Pair LABZ with either one: 1.41%. LABX + LABY gives 1.92%, almost a single 2% bet. And in stress, even LABZ's 0 may not hold.\",\"concept\":\"correlation-and-concentration\"}],\"check\":[\"q-2.11.3-1\",\"q-2.11.3-2\",\"q-2.11.3-3\"],\"recap\":{\"takeaways\":[\"Correlated positions act as one: two 1% positions at ρ = 0.9 swing like 1.95%.\",\"Effective bets = n ÷ (1 + (n − 1)ρ). Five positions at ρ = 0.8 are 1.19 bets.\",\"Look for the same bet in disguise, and expect correlations to rise in stress.\"],\"next\":\"Next, 2.11.4: caps per instrument, direction and theme, plus weekly and monthly loss limits that count open risk.\"}},\"2.11.4\":{\"unit\":\"2.11\",\"courseId\":\"2.11.4\",\"bridge\":\"In 2.11.2 you capped heat, and in 2.11.3 you found the same bet in disguise. Here both become written caps per instrument, direction and theme, and 1.4.9's daily loss limit grows into weekly and monthly limits that count open risk.\",\"hook\":{\"prompt\":\"Month-start equity is 10,000.00 and your monthly cap is 6%: 600.00. You have lost 350.00 and have 200.00 of open risk. How much new risk can you take?\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":300,\"step\":10,\"unit\":\"vUSD\",\"start\":0,\"answer\":50,\"tolerance\":0,\"feedback\":[{\"from\":0,\"to\":40,\"text\":\"There's a little more room than that: 600.00 − 350.00 − 200.00.\"},{\"from\":60,\"to\":300,\"text\":\"That leaves out the open risk. The 200.00 can still be lost, so it counts against the cap too.\"}]},\"compare\":\"You answered {yours}. 600.00 − 350.00 lost − 200.00 open = 50.00. A full 1% trade, 100.00, no longer fits this month.\",\"concept\":\"period-loss-limits\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Caps by instrument, direction and theme\",\"text\":\"An [[exposure-limit|exposure limit]] caps how much risk one idea can carry. One example policy: at most 2% of risk per instrument, at most half of your heat in one direction, and one position per correlated group. The numbers are conventions. The point is that no single instrument, direction or theme decides your month.\"},{\"kind\":\"worked\",\"title\":\"The monthly cap counts open risk\",\"lines\":[\"Alexander Elder's 6% rule: this month's losses plus open risk may not pass 6% of month-start equity.\",\"Room now: 600.00 − 350.00 − 200.00 = 50.00.\",\"The open trade then hits its stop and loses its 200.00. Room = 600.00 − 550.00 − 0 = ?\"],\"ask\":{\"answer\":50,\"tolerance\":0.01,\"unit\":\"vUSD\",\"feedback\":[{\"value\":250,\"text\":\"That treats the stop-out as new room. Realised losses rose to 550.00: 600.00 − 550.00.\"},{\"value\":0,\"text\":\"The stop-out cost exactly the 200.00 already counted as open risk. Nothing new was used up.\"}],\"correct\":\"Right. Still 50.00: the open risk was already counted, so the stop-out changed nothing.\"},\"after\":\"Counting open risk makes the [[monthly-loss-limit|monthly limit]] bite before the losses land, not after.\",\"concept\":\"period-loss-limits\"},{\"kind\":\"match\",\"title\":\"Sharks and piranhas\",\"prompt\":\"Elder compares one big loss to a shark bite and many small ones to piranhas. Match each rule to the damage it caps.\",\"pairs\":[{\"left\":\"2% per trade\",\"right\":\"The shark: one big loss\"},{\"left\":\"6% per month\",\"right\":\"The piranhas: many small losses\"},{\"left\":\"Heat cap\",\"right\":\"Every open stop hit at once\"},{\"left\":\"Daily loss limit\",\"right\":\"One bad day\"}],\"columns\":[\"Rule\",\"What it caps\"],\"concept\":\"period-loss-limits\"},{\"kind\":\"figure\",\"title\":\"Budgets on the calendar\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Per trade, 1%\",\"value\":100,\"role\":\"accent\"},{\"label\":\"Per day, 3%\",\"value\":300,\"role\":\"accent\"},{\"label\":\"Per week, 4%\",\"value\":400,\"role\":\"accent\"},{\"label\":\"Per month, 6%\",\"value\":600,\"role\":\"down\"}],\"unit\":\"vUSD\",\"steps\":[\"One trade may lose 1%: 100.00 of 10,000.00.\",\"A day may lose 3%, a week 4%. Example values, set before trading.\",\"The month may lose 6%, open risk included. Then trading stops until the 1st.\"]},\"text\":\"Each limit sits inside the next one. Weekly and monthly budgets stop a run of bad days, which a [[daily-loss-limit|daily limit]] alone can't.\",\"concept\":\"period-loss-limits\"},{\"kind\":\"predict\",\"title\":\"After a good week\",\"prompt\":\"Your losses hit the monthly cap on the 10th. You keep paper trading, and the next week goes well. Do you restart before the month ends?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"Yes: the good week shows the problem is over\",\"feedback\":\"A week of paper results is a small sample, and the cap exists for exactly this moment. It resets on the 1st.\"},{\"id\":\"b\",\"label\":\"No: the cap holds until the month ends\"}],\"answer\":\"b\"},\"reveal\":\"No. A limit you can reset early is only a suggestion. It resets on the 1st, measured from the new month-start equity. Use the pause to review the journal, not to look for a reason to restart.\",\"concept\":\"period-loss-limits\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"Fit the limits to how often you trade. At 2% per trade, three early losses end the month under a 6% rule, which critics call too tight for a professional. At 1% per trade it takes six. Set the numbers together, before the month starts.\"},{\"kind\":\"fields\",\"title\":\"Your limits\",\"prompt\":\"Set your own limits, in % of equity. They go into the Limits section of your plan.\",\"fields\":[{\"id\":\"perTrade\",\"label\":\"Risk per trade\",\"kind\":\"stepper\",\"min\":0.25,\"max\":2,\"step\":0.25,\"unit\":\"%\",\"default\":1},{\"id\":\"daily\",\"label\":\"Daily loss limit\",\"kind\":\"stepper\",\"min\":1,\"max\":6,\"step\":0.5,\"unit\":\"%\",\"default\":3},{\"id\":\"monthly\",\"label\":\"Monthly loss limit, open risk included\",\"kind\":\"stepper\",\"min\":2,\"max\":12,\"step\":1,\"unit\":\"%\",\"default\":6},{\"id\":\"instrument\",\"label\":\"Most risk in one instrument\",\"kind\":\"stepper\",\"min\":1,\"max\":4,\"step\":0.5,\"unit\":\"%\",\"default\":2},{\"id\":\"heat\",\"label\":\"Heat cap\",\"kind\":\"stepper\",\"min\":2,\"max\":10,\"step\":0.5,\"unit\":\"%\",\"default\":5}],\"valid\":{\"all\":[{\"field\":\"daily\",\"lte\":4},{\"field\":\"heat\",\"lte\":8}]},\"feedback\":[{\"when\":{\"field\":\"daily\",\"gt\":4},\"text\":\"A daily limit of {daily}% lets one day take a whole week's budget or more. This course uses 2% to 4%.\"},{\"when\":{\"field\":\"heat\",\"gt\":8},\"text\":\"A heat cap of {heat}% lets one bad afternoon take more than practitioners accept; they use about 4–8%.\"}],\"correct\":\"Saved. Before every order, the new trade must fit each of these at once.\",\"concept\":\"exposure-limits\"},{\"kind\":\"match\",\"title\":\"Five tickets\",\"prompt\":\"Limits: 1% per trade, 3% per day (nothing lost today), 6% per month with open risk, 2% per instrument, heat 5%, one position per correlated group. This month: −320.00. Open: LABX long and vEUR/vUSD long, 100.00 risk each.\",\"pairs\":[{\"left\":\"LABZ long, risk 50.00\",\"right\":\"Accept\"},{\"left\":\"LABZ long, risk 100.00\",\"right\":\"Resize\",\"wrong\":\"It fits the 1% trade cap and the heat cap, but the month has only 80.00 left: 600.00 − 320.00 − 200.00.\"},{\"left\":\"LABY long, risk 50.00\",\"right\":\"Reject\",\"wrong\":\"LABY moves with LABX (ρ 0.85), and LABX is already open: one position per correlated group.\"},{\"left\":\"Short vUSD/vCHF, risk 50.00\",\"right\":\"Reject\",\"wrong\":\"Selling vUSD/vCHF is a bet against vUSD, like your long vEUR/vUSD: the same group.\"},{\"left\":\"LABZ long, risk 150.00\",\"right\":\"Resize\",\"wrong\":\"150.00 breaks the 1% per-trade cap and the 80.00 left this month. Resize it to 80.00.\"}],\"columns\":[\"Ticket\",\"Decision\"],\"correct\":\"Right. Every ticket is checked against every limit, and the tightest one decides. This month, that's the 80.00 left.\",\"concept\":\"exposure-limits\"}],\"check\":[\"q-2.11.4-1\",\"q-2.11.4-2\",\"q-2.11.4-3\"],\"recap\":{\"takeaways\":[\"Cap risk per instrument, per direction and per theme, so no single idea decides your month.\",\"Monthly room = cap − realised losses − open risk: 600.00 − 350.00 − 200.00 = 50.00.\",\"A new trade must fit every limit at once; the tightest one sets the size.\"],\"next\":\"Next, 2.11.5: drawdown tiers, the rules that cut risk step by step as the account falls from its peak.\"}},\"2.11.5\":{\"unit\":\"2.11\",\"courseId\":\"2.11.5\",\"bridge\":\"In 2.11.4 your limits stopped new risk within a week or a month. A drawdown can run longer. In 1.4.8 you saw how deep a normal drawdown gets; here you set tiers that cut risk at preset depths, calibrated to your system's own simulated runs.\",\"hook\":{\"prompt\":\"At 1% risk, a simulated system has a median maximum drawdown of 8.3% over 100 trades; about 1 run in 20 goes past 14.8%. You set 'stop trading at −8%'. How often will a normal run trigger it?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"Rarely\"},{\"id\":\"b\",\"label\":\"About half the time\"},{\"id\":\"c\",\"label\":\"Almost always\"}],\"answer\":\"b\"},\"compare\":\"You picked {yours}. In 200,000 simulated runs, 54.3% reached −8%. A stop near the median fires in about half of perfectly normal runs.\",\"concept\":\"drawdown-tiers\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Tiers\",\"text\":\"A [[drawdown-tier|drawdown tier]] is a rule written in advance: at this depth below the peak, risk drops to that much. Tiers protect you when something has really changed, without waiting to be sure. This lesson uses one reference system: 40% winners at +2.5R, losers at −1R, risking 1% of current equity.\"},{\"kind\":\"worked\",\"title\":\"The recovery math\",\"lines\":[\"Gain needed to recover = DD ÷ (1 − DD).\",\"A 10% drawdown needs 10 ÷ 90 = 11.1%.\",\"A 20% drawdown needs 20 ÷ 80 = ?\"],\"ask\":{\"answer\":25,\"tolerance\":0.1,\"unit\":\"%\",\"feedback\":[{\"value\":20,\"text\":\"Recovering takes more than the loss, because the gain is earned on a smaller account: 20 ÷ 80.\"}],\"correct\":\"Right. 25%. Deeper holes get steeper to climb out of, which is why tiers cut risk early.\"},\"after\":\"At 50% it takes 100%. The deeper the hole, the more each extra point of [[drawdown]] costs.\",\"concept\":\"drawdown\"},{\"kind\":\"figure\",\"title\":\"Tiers on the underwater curve\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":0,\"h\":0,\"l\":0,\"c\":0},{\"o\":0,\"h\":0,\"l\":-1,\"c\":-1},{\"o\":-1,\"h\":-1,\"l\":-1.99,\"c\":-1.99},{\"o\":-1.99,\"h\":-1.99,\"l\":-2.97,\"c\":-2.97},{\"o\":-2.97,\"h\":-0.54,\"l\":-2.97,\"c\":-0.54},{\"o\":-0.54,\"h\":-0.54,\"l\":-1.54,\"c\":-1.54},{\"o\":-1.54,\"h\":-1.54,\"l\":-2.52,\"c\":-2.52},{\"o\":-2.52,\"h\":-2.52,\"l\":-3.5,\"c\":-3.5},{\"o\":-3.5,\"h\":-3.5,\"l\":-4.46,\"c\":-4.46},{\"o\":-4.46,\"h\":-4.46,\"l\":-5.42,\"c\":-5.42},{\"o\":-5.42,\"h\":-5.42,\"l\":-5.89,\"c\":-5.89},{\"o\":-5.89,\"h\":-4.72,\"l\":-5.89,\"c\":-4.72},{\"o\":-4.72,\"h\":-4.72,\"l\":-5.19,\"c\":-5.19},{\"o\":-5.19,\"h\":-4.01,\"l\":-5.19,\"c\":-4.01},{\"o\":-4.01,\"h\":-2.81,\"l\":-4.01,\"c\":-2.81},{\"o\":-2.81,\"h\":-0.38,\"l\":-2.81,\"c\":-0.38}],\"range\":[-11,1],\"describe\":\"Drawdown from the peak over 16 trades of the reference system with tiers. It reaches −5.42% after trade 10, bottoms at −5.89% after trade 11, recovers to −2.81% by trade 15 and −0.38% by trade 16.\"},\"steps\":[{\"text\":\"Each candle is one trade: how far equity sits below its peak, in %.\",\"layers\":[{\"kind\":\"level\",\"price\":0,\"role\":\"neutral\",\"label\":\"Peak\"}]},{\"text\":\"Trade 10 closes at −5.42%: tier 1 fires, and risk drops from 1% to 0.5%.\",\"layers\":[{\"kind\":\"level\",\"price\":-5,\"role\":\"concept\",\"label\":\"Tier 1: −5%\"},{\"kind\":\"marker\",\"index\":9,\"at\":\"close\",\"role\":\"down\"}]},{\"text\":\"The deepest point is −5.89%. By trade 15, half is recovered: risk returns to 1%.\",\"layers\":[{\"kind\":\"marker\",\"index\":10,\"at\":\"low\",\"label\":\"−5.89%\",\"role\":\"down\"},{\"kind\":\"marker\",\"index\":14,\"at\":\"close\",\"label\":\"Full risk\",\"role\":\"up\"}]},{\"text\":\"The second tier, stop and review at −10%, was never reached.\",\"layers\":[{\"kind\":\"level\",\"price\":-10,\"role\":\"stop\",\"label\":\"Tier 2: stop at −10%\"}]}]},\"text\":\"One simulated path of the reference system, with tier 1 at −5% and full risk back once half the drawdown is recovered.\",\"concept\":\"drawdown-tiers\"},{\"kind\":\"worked\",\"title\":\"A tier table\",\"lines\":[\"Tier 1, at −5%: risk drops from 1% to 0.5%.\",\"Tier 2, at −10%: stop trading and review every trade.\",\"Full risk returns once half the drawdown is recovered.\",\"Peak 10,000.00, equity 9,500.00: tier 1 is on. Risk per trade = 0.5% of 9,500.00 = ?\"],\"ask\":{\"answer\":47.5,\"tolerance\":0.01,\"unit\":\"vUSD\",\"feedback\":[{\"value\":95,\"text\":\"That's 1%. At −5%, tier 1 halves the risk: 0.5% of 9,500.00.\"},{\"value\":50,\"text\":\"That's 0.5% of the peak. Risk is a share of current equity: 9,500.00.\"}],\"correct\":\"Right. 47.50 a trade, until equity climbs back to 9,750.00.\"},\"after\":\"The Turtle traders' rules did something similar: they cut the equity they sized from by 20% for every 10% of drawdown.\",\"concept\":\"drawdown-tiers\"},{\"kind\":\"predict\",\"title\":\"Where the stop tier goes\",\"prompt\":\"Same system, no tiers. You put 'stop and review' at −10%. How often does a normal 100-trade run reach it?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"About 1 run in 20\",\"feedback\":\"About 1 run in 20 goes past 14.8%. −10% is much closer to normal: 30.7% of runs reach it.\"},{\"id\":\"b\",\"label\":\"About 1 run in 3\"},{\"id\":\"c\",\"label\":\"About 1 run in 2\",\"feedback\":\"That's −8%, near the median. −10% is reached in 30.7% of runs.\"}],\"answer\":\"b\"},\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Reach −5%\",\"value\":93.6,\"role\":\"down\"},{\"label\":\"Reach −8%\",\"value\":54.3,\"role\":\"down\"},{\"label\":\"Reach −10%\",\"value\":30.7,\"role\":\"down\"},{\"label\":\"Reach −15%\",\"value\":4.8,\"role\":\"neutral\"},{\"label\":\"Reach −20%\",\"value\":0.6,\"role\":\"neutral\"}],\"unit\":\"%\",\"steps\":[\"Share of 200,000 normal runs that reach each depth within 100 trades, at 1% risk.\"]},\"reveal\":\"30.7% of normal runs reach −10%. With tier 1 halving risk from −5%, only 7.6% do, and 1 run in 20 goes past 10.5% instead of 14.8%. The price: the median gain over 100 trades drops from +46.9% to +38.5%. Calibrate the stop tier with your other tiers in place.\",\"concept\":\"drawdown-tiers\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"Never raise risk to recover. Risk only goes down as the drawdown deepens, and comes back by a rule written in advance. Doubling up after losses is the [[martingale]] trap, and a long [[losing-streak|losing streak]] is exactly when it feels most tempting.\"},{\"kind\":\"fields\",\"title\":\"Your tiers\",\"prompt\":\"Write your tiers for the reference system at 1% risk. They go into your plan.\",\"fields\":[{\"id\":\"tier1Depth\",\"label\":\"Tier 1 depth\",\"kind\":\"stepper\",\"min\":3,\"max\":8,\"step\":1,\"unit\":\"%\",\"default\":5},{\"id\":\"tier1Risk\",\"label\":\"Risk per trade at tier 1\",\"kind\":\"choice\",\"options\":[0.25,0.5,0.75,1,1.5],\"unit\":\"%\",\"default\":1},{\"id\":\"stopDepth\",\"label\":\"Stop and review at\",\"kind\":\"stepper\",\"min\":10,\"max\":25,\"step\":1,\"unit\":\"%\",\"default\":10},{\"id\":\"returnPct\",\"label\":\"Full risk returns after recovering this share of the drawdown\",\"kind\":\"choice\",\"options\":[25,50,75,100],\"unit\":\"%\",\"default\":50},{\"id\":\"why\",\"label\":\"Why this stop depth fits\",\"kind\":\"text\",\"placeholder\":\"Needed if the stop is shallower than 15%\",\"required\":false,\"default\":\"\"}],\"valid\":{\"all\":[{\"field\":\"tier1Risk\",\"lt\":1},{\"any\":[{\"field\":\"stopDepth\",\"gte\":15},{\"field\":\"why\",\"ne\":\"\"}]}]},\"feedback\":[{\"when\":{\"field\":\"tier1Risk\",\"gte\":1},\"text\":\"Tier 1 has to cut risk. At {tier1Risk}% it keeps or raises it, just when the system is struggling.\"},{\"when\":{\"field\":\"stopDepth\",\"lt\":15},\"text\":\"Without other tiers, a stop at {stopDepth}% fires in more than 1 normal run in 20. Move it to 15% or deeper, or write why your tiers make it fit.\"}],\"correct\":\"Saved. Risk falls as the drawdown deepens, the stop sits where normal runs rarely reach, and a rule says when risk comes back.\",\"concept\":\"drawdown-tiers\"}],\"check\":[\"q-2.11.5-1\",\"q-2.11.5-2\",\"q-2.11.5-3\"],\"recap\":{\"takeaways\":[\"Tiers cut risk at preset depths, such as 1% to 0.5% at −5%, and say when it returns.\",\"Calibrate them to simulated normal runs: a stop at −8% fires in 54% of them.\",\"Risk only goes down as the drawdown deepens. Never raise it to recover.\"],\"next\":\"Next, 2.11.6: the performance metrics that read a journal, and what each of them hides.\"}},\"2.11.6\":{\"unit\":\"2.11\",\"courseId\":\"2.11.6\",\"bridge\":\"In 2.11.5 you calibrated tiers to a system's normal drawdowns. Now you read the rest of its record. In 1.6.4 you started a journal and in 1.6.7 you graded process; here you compute win rate, payoff, expectancy, profit factor and outlier dependence from one journal.\",\"hook\":{\"prompt\":\"System A wins 62% of trades with a profit factor of 1.15. System B wins 38% with a profit factor of 1.6. Losses are −1R in both. Which makes more per trade?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"System A\"},{\"id\":\"b\",\"label\":\"System B\"},{\"id\":\"c\",\"label\":\"The same\"}],\"answer\":\"b\"},\"compare\":\"You picked {yours}. B makes +0.37R a trade, A only +0.06R. A's high win rate hides small wins: 0.70R on average, against B's 2.61R.\",\"concept\":\"performance-metrics\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"Five numbers from a journal\",\"text\":\"From a [[journal]] in R: [[win-rate|win rate]] = wins ÷ trades. [[payoff-ratio|Payoff ratio]] = average win ÷ average loss. [[expectancy|Expectancy]] = net R ÷ trades. [[profit-factor|Profit factor]] = gross wins ÷ gross losses. Outlier dependence = best trade ÷ net R. Each looks at the same trades from a different side.\"},{\"kind\":\"worked\",\"title\":\"From profit factor to expectancy\",\"lines\":[\"E = (PF − 1) × (1 − W) × average loss, all in R.\",\"A: (1.15 − 1) × 0.38 × 1R = 0.057, about +0.06R.\",\"B: (1.6 − 1) × 0.62 × 1R = ?\"],\"ask\":{\"answer\":0.372,\"tolerance\":0.005,\"unit\":\"R\",\"feedback\":[{\"value\":0.6,\"text\":\"That's PF − 1. Multiply it by the loss rate, 1 − 0.38 = 0.62.\"},{\"value\":0.228,\"text\":\"That multiplies by the win rate. Use the loss rate: 0.62.\"}],\"correct\":\"Right. +0.37R a trade, more than six times A's.\"},\"after\":\"A profit factor of 1.15 sounds fine. At a 62% win rate it leaves almost nothing per trade.\",\"concept\":\"performance-metrics\"},{\"kind\":\"match\",\"title\":\"What each metric hides\",\"prompt\":\"[[recovery-factor|Recovery factor]] is net profit ÷ maximum drawdown. Match each metric to what it hides.\",\"pairs\":[{\"left\":\"Win rate\",\"right\":\"How big the wins are next to the losses\"},{\"left\":\"Profit factor\",\"right\":\"The order of trades, and so the drawdown\"},{\"left\":\"Maximum drawdown\",\"right\":\"That it rests on a single episode\"},{\"left\":\"Recovery factor\",\"right\":\"That it grows with the length of the record\"}],\"columns\":[\"Metric\",\"What it hides\"],\"concept\":\"performance-metrics\"},{\"kind\":\"worked\",\"title\":\"Outlier dependence\",\"lines\":[\"A trend-following record: net +40R over a year.\",\"Its best trade: +15R.\",\"Outlier dependence = 15 ÷ 40 = ?\"],\"ask\":{\"answer\":37.5,\"tolerance\":0.1,\"unit\":\"%\",\"feedback\":[{\"value\":2.67,\"text\":\"That's 40 ÷ 15, upside down. Divide the best trade by the net result.\"}],\"correct\":\"Right. 37.5%: without that one trade, the year made +25R.\"},\"after\":\"Trend following needs a few outliers; that's how it works. Know how much of your result rests on them.\",\"concept\":\"performance-metrics\"},{\"kind\":\"figure\",\"title\":\"Process on top\",\"figure\":{\"kind\":\"bars\",\"bars\":[{\"label\":\"Plan adherence\",\"value\":91.7,\"role\":\"accent\"},{\"label\":\"Stop integrity\",\"value\":100,\"role\":\"accent\"},{\"label\":\"Risk accuracy\",\"value\":83.3,\"role\":\"accent\"},{\"label\":\"Win rate (n = 12)\",\"value\":41.7,\"role\":\"neutral\"}],\"unit\":\"%\",\"steps\":[\"Twelve trades. Process first: 11 of 12 followed the plan, and all 12 kept their stop.\",\"Risk accuracy: 10 of 12 were sized within the limit.\",\"Win rate: 5 of 12. Greyed out, because 12 trades say little about outcomes.\"]},\"text\":\"Grade yourself on [[process-kpi|process KPIs]]: they depend on your actions and mean something after a few trades. Outcome metrics stay diagnostics, folded away until about 30 trades and always shown with their [[sample-size|sample size]].\",\"concept\":\"process-kpis\"},{\"kind\":\"callout\",\"tone\":\"warning\",\"text\":\"A profit factor above 3 in a backtest is a warning, not a trophy. It usually means too few trades, or rules fitted to the past. That's a practitioners' rule of thumb, not a law: check the sample size and test on new data before you believe it.\"},{\"kind\":\"worked\",\"title\":\"The journal, two more numbers\",\"lines\":[\"Journal: 40 trades. 16 wins, +40R in total; 24 losses, −24R in total. Best trade +9R.\",\"Net: +16R. Without the best trade: +7R.\",\"Profit factor = 40 ÷ 24 = ?\"],\"ask\":{\"answer\":1.67,\"tolerance\":0.01,\"feedback\":[{\"value\":0.6,\"text\":\"That's 24 ÷ 40, upside down. Gross wins go on top.\"},{\"value\":16,\"text\":\"16R is the net result. Profit factor divides gross wins by gross losses.\"}],\"correct\":\"Right. 1.67.\"},\"after\":\"Outlier dependence: 9 ÷ 16 = 56%. One trade made more than half the net. Now set the rest in the Try.\",\"concept\":\"performance-metrics\"}],\"task\":{\"widget\":\"expectancy\",\"goal\":\"Same journal: 40 trades, 16 wins totalling +40R, 24 losses totalling −24R. Set the win rate, the average win and the average loss, then read the expectancy.\",\"start\":{\"winRate\":45,\"avgWin\":2,\"avgLoss\":1,\"runLength\":5},\"locked\":[\"runLength\"],\"hidden\":[\"runProb\"],\"success\":{\"all\":[{\"field\":\"winRate\",\"eq\":40},{\"field\":\"avgWin\",\"eq\":2.5},{\"field\":\"avgLoss\",\"eq\":1}]},\"feedback\":[{\"when\":{\"field\":\"winRate\",\"eq\":16},\"text\":\"16 is the number of wins. Win rate = 16 ÷ 40 trades.\"},{\"when\":{\"field\":\"winRate\",\"ne\":40},\"text\":\"Win rate = wins ÷ all trades: 16 ÷ 40.\"},{\"when\":{\"field\":\"avgWin\",\"eq\":1.7},\"text\":\"That's close to the profit factor, 40 ÷ 24. The average win is 40R ÷ 16 wins.\"},{\"when\":{\"field\":\"avgWin\",\"ne\":2.5},\"text\":\"Average win = gross wins ÷ number of wins: 40R ÷ 16.\"},{\"when\":{\"field\":\"avgLoss\",\"ne\":1},\"text\":\"Average loss = gross losses ÷ number of losses: 24R ÷ 24.\"}],\"correct\":\"Right. Win rate 40%, payoff 2.5, expectancy +0.40R a trade. With profit factor 1.67 and outlier dependence 56%, that's the whole card. On 40 trades, all of it is still a diagnostic.\",\"hints\":[\"Each figure is a total divided by a count.\",\"Win rate 16 ÷ 40. Average win 40R ÷ 16. Average loss 24R ÷ 24.\"],\"showMe\":{\"winRate\":40,\"avgWin\":2.5,\"avgLoss\":1},\"concept\":\"performance-metrics\"},\"check\":[\"q-2.11.6-1\",\"q-2.11.6-2\",\"q-2.11.6-3\"],\"recap\":{\"takeaways\":[\"One journal, five views: win rate, payoff, expectancy, profit factor, outlier dependence.\",\"Each hides something: win rate hides payoff, profit factor hides order, drawdown rests on one episode.\",\"Grade the process. Read outcome metrics as diagnostics, next to their sample size.\"],\"next\":\"Next, 2.11.7: how sure you can be of an expectancy, with a confidence interval around it.\"}},\"2.11.7\":{\"unit\":\"2.11\",\"courseId\":\"2.11.7\",\"bridge\":\"In 2.11.6 you computed expectancy as one number. In 0.2.4 a win rate from 20 trades turned out to be a wide range, and 2.8.10 put ±0.40R around 50 trades. Here you build that interval for expectancy and count the trades needed.\",\"hook\":{\"prompt\":\"Your setup shows +0.40R per trade over 20 trades, with a spread of results of 1.71R. How sure can you be that the true expectancy is above zero?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"Very sure\"},{\"id\":\"b\",\"label\":\"Fairly sure\"},{\"id\":\"c\",\"label\":\"Not sure at all\"}],\"answer\":\"c\"},\"compare\":\"You picked {yours}. The 95% interval runs from −0.35R to +1.15R. Zero sits well inside it: 20 trades can't tell this edge from none.\",\"concept\":\"expectancy-confidence-interval\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"How far the average can be off\",\"text\":\"An average from a sample is an estimate. Its standard error = sd ÷ √n, where sd is the spread of single results and n the [[sample-size|sample size]]. A 95% [[confidence-interval|confidence interval]] is the average ± 1.96 standard errors. Four times the trades halve its width.\"},{\"kind\":\"worked\",\"title\":\"The interval at 20 trades\",\"lines\":[\"Mean +0.40R, sd 1.71R, n = 20. √20 = 4.47.\",\"Half-width = 1.96 × 1.71 ÷ 4.47 = ?\"],\"ask\":{\"answer\":0.75,\"tolerance\":0.01,\"unit\":\"R\",\"feedback\":[{\"value\":0.38,\"text\":\"That's one standard error, 1.71 ÷ 4.47. A 95% interval takes 1.96 of them.\"},{\"value\":3.35,\"text\":\"That's 1.96 × 1.71, not yet divided by √20.\"}],\"correct\":\"Right. 0.75R on each side: from −0.35R to +1.15R.\"},\"after\":\"The true expectancy could be negative, or nearly three times what you measured.\",\"concept\":\"expectancy-confidence-interval\"},{\"kind\":\"worked\",\"title\":\"The same for a win rate\",\"lines\":[\"22 wins in 40 trades: 55%. Standard error = √(0.55 × 0.45 ÷ 40) = 0.0787.\",\"Half-width = 1.96 × 0.0787 = 0.154, or 15.4 points.\",\"Lower end = 55% − 15.4% = ?\"],\"ask\":{\"answer\":39.6,\"tolerance\":0.1,\"unit\":\"%\",\"feedback\":[{\"value\":47.1,\"text\":\"That subtracts one standard error. A 95% interval uses 1.96 of them: 15.4 points.\"}],\"correct\":\"Right. 39.6% to 70.4%: the true win rate could be under 40% or over 70%.\"},\"concept\":\"expectancy-confidence-interval\"},{\"kind\":\"figure\",\"title\":\"The interval narrows\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":0.4,\"h\":0.4,\"l\":0.4,\"c\":0.4},{\"o\":0.4,\"h\":0.4,\"l\":0.4,\"c\":0.4},{\"o\":0.4,\"h\":0.4,\"l\":0.4,\"c\":0.4},{\"o\":0.4,\"h\":0.4,\"l\":0.4,\"c\":0.4}],\"hideCandles\":true,\"range\":[-0.5,1.3],\"describe\":\"Four 95% intervals for a mean of +0.40R with sd 1.71R: −0.35R to +1.15R at 20 trades, −0.07R to +0.87R at 50, +0.06R to +0.74R at 100, +0.23R to +0.57R at 400.\"},\"steps\":[{\"text\":\"20 trades: −0.35R to +1.15R. Zero is well inside.\",\"layers\":[{\"kind\":\"level\",\"price\":0,\"role\":\"neutral\",\"label\":\"Zero\"},{\"kind\":\"level\",\"price\":0.4,\"role\":\"concept\",\"label\":\"Mean +0.40R\"},{\"kind\":\"bracket\",\"from\":-0.35,\"to\":1.15,\"index\":0,\"label\":\"n = 20\",\"role\":\"neutral\"}]},{\"text\":\"50 trades: −0.07R to +0.87R. Zero is still inside.\",\"layers\":[{\"kind\":\"bracket\",\"from\":-0.07,\"to\":0.87,\"index\":1,\"label\":\"n = 50\",\"role\":\"neutral\"}]},{\"text\":\"100 trades: +0.06R to +0.74R. Zero is just outside.\",\"layers\":[{\"kind\":\"bracket\",\"from\":0.06,\"to\":0.74,\"index\":2,\"label\":\"n = 100\",\"role\":\"up\"}]},{\"text\":\"400 trades: +0.23R to +0.57R. Four times the trades, half the width.\",\"layers\":[{\"kind\":\"bracket\",\"from\":0.23,\"to\":0.57,\"index\":3,\"label\":\"n = 400\",\"role\":\"up\"}]}]},\"text\":\"The reference system: 40% winners at +2.5R, losers at −1R. Its true expectancy is +0.40R, and still 50 trades can't show it.\",\"concept\":\"expectancy-confidence-interval\"},{\"kind\":\"predict\",\"title\":\"A system with no edge\",\"prompt\":\"A system with no edge and an sd of 1.7R is traded 30 times. How often does it show an average of +0.40R or better, by luck alone?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"About 1 time in 100\",\"feedback\":\"Luck is more generous than that. Over 30 trades the standard error is 0.31R, so +0.40R is only 1.29 of them away.\"},{\"id\":\"b\",\"label\":\"About 1 time in 10\"},{\"id\":\"c\",\"label\":\"About 1 time in 2\",\"feedback\":\"+0.40R sits 1.29 standard errors above zero, so it's rarer than that: about 1 time in 10.\"}],\"answer\":\"b\"},\"reveal\":\"About 1 time in 10. Over 30 trades the standard error is 1.7 ÷ √30 = 0.31R, and +0.40R is 1.29 of them above zero: 9.9% of no-edge samples get there. Of ten people testing useless setups, one looks like a winner.\",\"concept\":\"base-rates\"},{\"kind\":\"worked\",\"title\":\"How many trades you need\",\"lines\":[\"For an interval that just excludes zero, you need t ≈ 2: n = (2 × sd ÷ mean)².\",\"Edge +0.20R, sd 1.5R: 2 × 1.5 ÷ 0.20 = 15.\",\"n = 15² = ?\"],\"ask\":{\"answer\":225,\"tolerance\":0,\"unit\":\"trades\",\"feedback\":[{\"value\":30,\"text\":\"That's 2 × 15. Square it: 15 × 15.\"},{\"value\":15,\"text\":\"Square it: n = 15².\"}],\"correct\":\"Right. 225 trades. Half the edge needs four times the trades.\"},\"after\":\"At +0.40R and sd 1.71R, the same rule gives 73 trades. Small edges need hundreds of trades before they show.\",\"concept\":\"expectancy-confidence-interval\"},{\"kind\":\"callout\",\"tone\":\"info\",\"text\":\"All of this assumes each trade is independent of the last. Streaky results, or trades that share one market move, make the real interval wider. More on that in 3.10.\"},{\"kind\":\"predict\",\"title\":\"Find the sample size\",\"prompt\":\"Mean +0.40R, sd 1.71R. Find the smallest number of trades at which the 95% interval excludes zero.\",\"control\":{\"kind\":\"slider\",\"min\":20,\"max\":120,\"step\":1,\"unit\":\"trades\",\"start\":20,\"answer\":71,\"tolerance\":0,\"feedback\":[{\"from\":20,\"to\":70,\"text\":\"Not yet. At 70 trades the half-width is 0.4006R, just above the 0.40R mean, so the interval still reaches below zero.\"},{\"from\":72,\"to\":120,\"text\":\"That works, but fewer trades already do. At 71 the half-width is 0.3978R.\"}]},\"reveal\":\"71. At 70, 1.96 × 1.71 ÷ √70 = 0.4006R, just above the mean. At 71 it's 0.3978R, and the interval starts at +0.002R. The rule of thumb, with 2 instead of 1.96, gives 73: close enough to plan with.\",\"concept\":\"expectancy-confidence-interval\"}],\"check\":[\"q-2.11.7-1\",\"q-2.11.7-2\",\"q-2.11.7-3\"],\"recap\":{\"takeaways\":[\"95% interval = mean ± 1.96 × sd ÷ √n. At 20 trades: −0.35R to +1.15R.\",\"Trades needed ≈ (2 × sd ÷ mean)². +0.20R with sd 1.5R needs about 225.\",\"A no-edge system shows +0.40R over 30 trades about 1 time in 10.\"],\"next\":\"Next, 2.11.8: SQN, one score from the mean, spread and number of trades, and comparing two systems fairly.\"}},\"2.11.8\":{\"unit\":\"2.11\",\"courseId\":\"2.11.8\",\"bridge\":\"In 2.11.7 you put an interval around expectancy. SQN folds the same mean, spread and trade count into one score. Then, as in 2.8.10, you compare systems after costs and next to holding, this time per month instead of per trade.\",\"hook\":{\"prompt\":\"System A: +0.40R per trade, 8 trades a month. System B: +1.00R per trade, 2 trades a month. Which earns more per month?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"System A\"},{\"id\":\"b\",\"label\":\"System B\"},{\"id\":\"c\",\"label\":\"The same\"}],\"answer\":\"a\"},\"compare\":\"You picked {yours}. A: 8 × 0.40 = 3.2R a month; B: 2 × 1.00 = 2.0R. After costs of 0.10R a trade: 2.4R against 1.8R.\",\"concept\":\"sqn\"},\"learn\":[{\"kind\":\"explain\",\"title\":\"One score for an edge\",\"text\":\"[[sqn|SQN]], the system quality number, is √N × mean R ÷ sd of R, with N capped at 100. Uncapped, it's the t-statistic of the mean from 2.11.7: how many standard errors the average sits above zero. Van Tharp popularised it; the cap stops a long record from inflating it.\"},{\"kind\":\"worked\",\"title\":\"SQN of the reference system\",\"lines\":[\"100 trades, mean +0.40R, sd 1.71R.\",\"SQN = √100 × 0.40 ÷ 1.71 = 10 × 0.40 ÷ 1.71 = ?\"],\"ask\":{\"answer\":2.34,\"tolerance\":0.01,\"feedback\":[{\"value\":0.23,\"text\":\"That leaves out √100 = 10. Multiply 0.40 ÷ 1.71 by 10.\"},{\"value\":23.39,\"text\":\"That multiplies by 100. SQN uses its square root, 10.\"}],\"correct\":\"Right. 2.34: the mean sits 2.34 standard errors above zero, p ≈ 0.02 two-sided.\"},\"after\":\"Tharp also published bands for SQN, from 'hard to trade' to 'excellent'. They're a practitioner's rule of thumb, not a test: read the number as a t-statistic.\",\"concept\":\"sqn\"},{\"kind\":\"predict\",\"title\":\"SQN on 20 trades\",\"prompt\":\"A new setup shows an SQN of 3.1 after 20 trades. Is that reliable?\",\"control\":{\"kind\":\"choice\",\"choices\":[{\"id\":\"a\",\"label\":\"Yes: SQN already allows for the number of trades\",\"feedback\":\"√N is in the formula, but the mean and the sd themselves come from 20 trades. Both can be far off.\"},{\"id\":\"b\",\"label\":\"No: 20 trades are too few to trust it\"}],\"answer\":\"b\"},\"reveal\":\"No. On 20 trades, SQN rests on a mean and an sd that are rough guesses themselves: in 2.11.7, the interval for a 20-trade mean ran from −0.35R to +1.15R. Wait for about 100 trades, the cap, before reading it.\",\"concept\":\"sqn\"},{\"kind\":\"worked\",\"title\":\"Opportunity per month\",\"lines\":[\"Opportunity = (expectancy − costs) × trades per month.\",\"A: (0.40 − 0.10) × 8 = 2.4R a month.\",\"B: (1.00 − 0.10) × 2 = ?\"],\"ask\":{\"answer\":1.8,\"tolerance\":0.01,\"unit\":\"R\",\"feedback\":[{\"value\":2,\"text\":\"That's B before costs. Take 0.10R off each trade first.\"},{\"value\":0.9,\"text\":\"That's per trade. B trades twice a month.\"}],\"correct\":\"Right. 1.8R. A still earns more a month, but its lead shrinks from 1.2R to 0.6R, because it pays costs four times as often.\"},\"concept\":\"expectancy\"},{\"kind\":\"figure\",\"title\":\"Next to the benchmark\",\"figure\":{\"kind\":\"chart\",\"chart\":{\"candles\":[{\"o\":10000,\"h\":10582.25,\"l\":10000,\"c\":10582.25},{\"o\":10582.25,\"h\":10582.25,\"l\":10314.73,\"c\":10314.73},{\"o\":10314.73,\"h\":10333.25,\"l\":10314.73,\"c\":10333.25},{\"o\":10333.25,\"h\":10351.79,\"l\":10333.25,\"c\":10351.79},{\"o\":10351.79,\"h\":10658.42,\"l\":10351.79,\"c\":10658.42},{\"o\":10658.42,\"h\":10677.57,\"l\":10658.42,\"c\":10677.57},{\"o\":10677.57,\"h\":10696.76,\"l\":10677.57,\"c\":10696.76},{\"o\":10696.76,\"h\":10696.76,\"l\":10426.35,\"c\":10426.35},{\"o\":10426.35,\"h\":10735.21,\"l\":10426.35,\"c\":10735.21},{\"o\":10735.21,\"h\":10754.48,\"l\":10735.21,\"c\":10754.48},{\"o\":10754.48,\"h\":11073.05,\"l\":10754.48,\"c\":11073.05},{\"o\":11073.05,\"h\":11717.75,\"l\":11073.05,\"c\":11717.75},{\"o\":11717.75,\"h\":11738.8,\"l\":11717.75,\"c\":11738.8},{\"o\":11738.8,\"h\":11759.89,\"l\":11738.8,\"c\":11759.89},{\"o\":11759.89,\"h\":12444.61,\"l\":11759.89,\"c\":12444.61},{\"o\":12444.61,\"h\":12813.27,\"l\":12444.61,\"c\":12813.27},{\"o\":12813.27,\"h\":12813.27,\"l\":12489.37,\"c\":12489.37},{\"o\":12489.37,\"h\":12489.37,\"l\":11844.65,\"c\":11844.65},{\"o\":11844.65,\"h\":11865.93,\"l\":11844.65,\"c\":11865.93},{\"o\":11865.93,\"h\":12217.42,\"l\":11865.93,\"c\":12217.42},{\"o\":12217.42,\"h\":12928.74,\"l\":12217.42,\"c\":12928.74},{\"o\":12928.74,\"h\":12928.74,\"l\":12601.93,\"c\":12601.93},{\"o\":12601.93,\"h\":12601.93,\"l\":12283.36,\"c\":12283.36},{\"o\":12283.36,\"h\":12283.36,\"l\":11972.86,\"c\":11972.86}],\"style\":\"line\",\"describe\":\"Month-end equity over 24 months. The simulated system ends at 11,972.86 (+19.73%) with a maximum drawdown of 7.56%. Holding LABX ends at 12,974.79 (+29.75%) with a maximum drawdown of 12.42%.\"},\"steps\":[{\"text\":\"A simulated system at 1% risk, built to average +0.10R a trade after costs: +19.73% in 24 months.\",\"layers\":[{\"kind\":\"marker\",\"index\":23,\"at\":\"close\",\"label\":\"11,972.86\",\"role\":\"accent\"}]},{\"text\":\"The ghost: the same 10,000.00 held in LABX. It ends at 12,974.79, up 29.75%.\",\"layers\":[{\"kind\":\"line\",\"values\":[10877,11272,11479.44,11510.29,11397.87,11127.65,11288.53,11740,11437.35,11204.1,11162.13,11181.17,12018.93,12559.7,12383.15,13253.2,11606.9,12186.01,12136.01,12434.07,12430.73,12508.17,12928.75,12974.79],\"role\":\"neutral\",\"dashed\":true,\"label\":\"Holding LABX\"}]},{\"text\":\"Holding fell 12.42% at worst, the system 7.56%. Weigh return and drawdown together.\",\"layers\":[{\"kind\":\"bracket\",\"from\":11606.9,\"to\":13253.2,\"index\":16,\"label\":\"−12.42%\",\"role\":\"down\"},{\"kind\":\"bracket\",\"from\":11844.65,\"to\":12813.27,\"index\":17,\"label\":\"−7.56%\",\"role\":\"accent\"}]}]},\"text\":\"Making money isn't the test. The question is whether a system beats simply holding the market, with its risk counted. This one trailed the [[benchmark]] on return, though it fell less on the way.\",\"concept\":\"passive-benchmark\"},{\"kind\":\"callout\",\"tone\":\"key\",\"text\":\"More trades help only if each one still has an edge after costs. Doubling the frequency of a thin setup doubles its costs too. Compare systems by R per month, net of costs, and set the result next to the passive benchmark before calling anything good.\"},{\"kind\":\"predict\",\"title\":\"The cost that evens them out\",\"prompt\":\"A: +0.40R a trade, 8 a month. B: +1.00R a trade, 2 a month. At what cost per trade, in R, do they earn the same per month?\",\"control\":{\"kind\":\"slider\",\"min\":0,\"max\":0.5,\"step\":0.05,\"unit\":\"R\",\"start\":0,\"answer\":0.2,\"tolerance\":0,\"feedback\":[{\"from\":0,\"to\":0.15,\"text\":\"A still earns more here. At 0.15R a trade: A 2.0R, B 1.7R a month.\"},{\"from\":0.25,\"to\":0.5,\"text\":\"B is ahead here. At 0.25R a trade: A 1.2R, B 1.5R a month.\"}]},\"reveal\":\"0.20R. (0.40 − c) × 8 = (1.00 − c) × 2 gives 6c = 1.2, so c = 0.20: both earn 1.6R a month. Above that, the frequent system loses its lead, because costs scale with every trade.\",\"concept\":\"expectancy\"}],\"check\":[\"q-2.11.8-1\",\"q-2.11.8-2\",\"q-2.11.8-3\"],\"recap\":{\"takeaways\":[\"SQN = √N × mean ÷ sd, with N capped at 100. The reference system scores 2.34.\",\"Compare per month after costs: (0.40 − 0.10) × 8 = 2.4R beats (1.00 − 0.10) × 2 = 1.8R.\",\"Set every system next to the passive benchmark, drawdowns included, before calling it good.\"],\"next\":\"Next: the 2.11 checkpoint, then unit 2.12, The trader's mind II, starting with 2.12.1: why losses feel bigger than gains.\"}}}");
